-- Auto-generated by scripts/curriculum/build-level-sql.mjs -- do not
-- hand-edit the lesson content below; regenerate from the source plan
-- JSON instead if something needs to change.

do $$
declare
  v_course_id uuid := 'b5323c09-0111-4c75-bdf8-50a9979e83f1';
  v_level uuid;
  -- modules.order_number is unique per COURSE, not per level (a course's
  -- modules are numbered continuously across all its levels) -- so this
  -- can't just start at 1 for a level beyond the first. Computed here
  -- instead of hardcoded so this script works correctly regardless of how
  -- many modules the course already has.
  v_module_offset int;
  v_m1 uuid;
  v_m2 uuid;
begin
  -- Appending to a level that already exists. Looked up rather than
  -- inserted, so this adds to the learner's current Level 1 instead of
  -- creating a duplicate one, and no existing module is re-parented.
  select id into v_level from public.levels
    where course_id = v_course_id and order_number = 1;

  if v_level is null then
    raise exception 'Level % not found for course % -- refusing to guess', 1, v_course_id;
  end if;

  -- The new modules must sit INSIDE this level, not at the end of the
  -- course. getOrderedLessons() builds the learner's lesson sequence from
  -- modules.order_number alone and ignores level, so a module appended at
  -- the course's max order would put beginner content after the final
  -- level's material. Insert straight after this level's last module and
  -- shift everything below it down instead.
  select coalesce(max(order_number), 0) into v_module_offset
    from public.modules where level_id = v_level;

  -- Two-phase shift: (course_id, order_number) is unique, and a single
  -- "+ N" update can trip that constraint mid-statement, so park the rows
  -- out of range first and bring them back afterwards.
  update public.modules set order_number = order_number + 1000
   where course_id = v_course_id and order_number > v_module_offset;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Actually Building the Site', 'The existing lessons explain what WordPress is and how to choose hosting. This one is where a page finally appears — the dashboard, and the editor you will spend all your time in.', v_module_offset + 1)
  returning id into v_m1;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m1, 'Finding Your Way Around the Dashboard', 'WordPress''s own tour of the dashboard — the control centre behind every WordPress site, and what each section is for. About 7 minutes.', 'https://www.youtube.com/watch?v=VCgWDVu-tOw', 1,
      array['Find posts, pages, media, appearance, plugins and settings', 'Tell the difference between a post and a page and use each correctly', 'Set the site title, tagline and permalink structure before publishing'],
      'The dashboard is where every WordPress site is run, and it looks the same whether the site is a one-page business card or a newspaper.

THE SECTIONS YOU WILL USE, and what each is really for:

POSTS versus PAGES, which confuses every beginner. A POST is dated content in a stream — news, blog entries, updates — and it appears in reverse chronological order with categories and tags. A PAGE is standing content that does not belong to a date: About, Services, Contact. If you find yourself giving a page a date, it should probably be a post.

MEDIA holds every image and file you upload. WordPress keeps several resized copies of each image automatically, which is helpful, and it never cleans up files you stop using, which is not.

APPEARANCE controls the theme, the menus and the widgets — what the site looks like.

PLUGINS add features. Settings holds the site-wide options.

THREE SETTINGS TO FIX BEFORE YOU PUBLISH ANYTHING:

SITE TITLE AND TAGLINE, under Settings > General. The default tagline is "Just another WordPress site" and it appears in search results and browser tabs on a shocking number of live business sites.

PERMALINKS, under Settings > Permalinks. Set it to Post name so your URLs read `yoursite.co.ke/about` rather than `?p=42`. Do this FIRST — changing it later breaks every link anyone has already shared, and search engines have to relearn the whole site.

SEARCH ENGINE VISIBILITY, under Settings > Reading. There is a checkbox that asks search engines not to index the site. It is useful while you build, and forgetting to untick it on launch day is one of the most common and most costly WordPress mistakes there is — the site simply never appears in Google, and nothing looks wrong.

AND KEEP THE ADMIN ACCOUNT SEPARATE from the one you write with, on any site with more than one person. WordPress user roles — Administrator, Editor, Author, Contributor, Subscriber — exist precisely so a writer cannot accidentally delete a plugin.',
      'On a WordPress site — a local install, a free WordPress.com site, or a client''s — do four things: set the site title and a real tagline, set permalinks to Post name, confirm the search engine visibility box is UNTICKED if the site is live, and create one page and one post so you can see where each appears. Then look at the media library and note how many copies of one upload WordPress made.',
      '[{"question":"When should you set the permalink structure?","options":["Before publishing anything — changing it later breaks every shared link","After the site has been live for a month","Only if you use a custom theme","It cannot be changed once the site is created"],"correct_index":0},{"question":"The site is live but never appears in Google, and nothing looks broken. What should you check first?","options":["Settings > Reading, for the box asking search engines not to index the site","The theme''s colour settings","Whether the media library is full","The number of installed plugins"],"correct_index":0}]'::jsonb),
    (v_m1, 'Building Pages with the Block Editor', 'WordPress''s own lesson on the Block Editor — creating posts and pages, and arranging content in blocks. About 8 minutes.', 'https://www.youtube.com/watch?v=DaaCThv_NNM', 2,
      array['Build a page from blocks and rearrange them', 'Use List View to manage a page that has grown complicated', 'Reuse a layout instead of rebuilding it each time'],
      'Everything on a modern WordPress page is a BLOCK: a paragraph, a heading, an image, a button, a gallery, a column layout. You add blocks with the + button or by typing `/` followed by the block name, which is much faster once it is a habit.

THE BLOCKS THAT DO ALMOST EVERYTHING: paragraph, heading, image, button, columns, spacer, and list. A capable business page is usually those seven.

HEADINGS ARE STRUCTURE, NOT SIZE. Use H1 once for the page title, then H2 for main sections and H3 beneath them, in order. Do not pick a heading level because you like how big it looks — screen readers navigate by that structure, and search engines read it as the page''s outline. Change the appearance with styling, not by skipping levels.

LIST VIEW is the button that saves you once a page gets long. It shows every block as a tree, so you can select the one you cannot click on and drag things reliably. Beginners fight with nested blocks for months before discovering it.

GROUPS AND COLUMNS nest, which is how real layouts get built — a group holding two columns, each holding an image and a paragraph. Nesting is also how pages become impossible to edit, so keep it shallow.

PATTERNS AND SYNCED PATTERNS (once called reusable blocks) let you save a layout and drop it in again — a call-to-action, a contact strip. A SYNCED pattern updates everywhere when you change it, which is right for a phone number and wrong for text you want to vary per page.

PREVIEW ON A PHONE BEFORE PUBLISHING. The editor shows a desktop-width canvas by default, and most Kenyan visitors will arrive on a phone. Use the preview dropdown to check mobile, and keep images light — a page heavy with full-size photos costs your visitor real money in data and loses them before it loads.

AND SAVE A DRAFT AS YOU GO. WordPress autosaves, but a lost connection mid-edit is a common way to lose twenty minutes of work.',
      'Build one real page — an About or Services page — using at least a heading, paragraph, image, columns and a button block. Set the heading levels properly: one H1, then H2s in order. Open List View and use it to reorder two blocks. Then preview it at mobile width and fix anything that breaks. Publish it and open the live URL on your own phone.',
      '[{"question":"Why choose heading levels by structure rather than by how big they look?","options":["Screen readers and search engines read the heading order as the page''s outline","WordPress refuses to publish pages with the wrong sizes","Larger headings slow the page down","Heading levels control the page''s colour scheme"],"correct_index":0},{"question":"A block is nested so deeply you cannot click it. What is the fix?","options":["Open List View and select it from the block tree","Delete the surrounding blocks and rebuild","Switch to the classic editor","Zoom in until it becomes clickable"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Design, Plugins, and Keeping the Site Alive', 'Choosing how the site looks, extending what it can do, and the maintenance that decides whether it is still working in a year.', v_module_offset + 2)
  returning id into v_m2;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m2, 'Choosing a Theme and Designing the Site', 'WordPress.com''s complete beginner course — choosing a theme, designing a homepage, adding pages and customising the look. About 48 minutes, so watch it across two or three sittings.', 'https://www.youtube.com/watch?v=sqqVQSeMO-M', 1,
      array['Choose a theme on the right criteria rather than on the demo screenshot', 'Customise colours, fonts and the homepage layout', 'Build a navigation menu a visitor can actually use'],
      'This one runs about 48 minutes. On a mobile bundle that is a real cost, so watch it in two or three sittings — the theme and homepage sections first, menus and customisation after.

HOW TO CHOOSE A THEME, because the demo screenshot is the worst possible basis:
- WHEN WAS IT LAST UPDATED? Anything untouched for over a year is a security and compatibility risk. This single check eliminates most bad choices.
- HOW MANY ACTIVE INSTALLATIONS, and what do recent reviews say — recent, not the five-year-old five-star ones.
- IS IT FAST? Themes stuffed with sliders, animations and page-builders are slow, and slow is expensive for a visitor paying for data.
- DOES IT DO WHAT YOU NEED WITHOUT A PILE OF PLUGINS?

The default WordPress themes — Twenty Twenty-Four and its successors — are genuinely good, fast, maintained by the project itself and free. Beginners dismiss them because they look plain in the demo, then spend a week fighting a flashy one.

DO NOT REDESIGN A LIVE SITE IN PUBLIC. Use a staging copy, or at least make big changes at your quietest hour.

MENUS ARE NAVIGATION, and navigation is most of usability. Five to seven top-level items at most; a visitor who cannot find Contact in three seconds leaves. Order them by what people actually want, not by your internal structure — Services and Contact outrank About every time.

CUSTOMISE LESS THAN YOU WANT TO. Two fonts and a small colour palette read as professional; five of each reads as amateur, and it is the fastest way to make a competent site look untrustworthy.

AND CHECK EVERY CHANGE ON A PHONE. A theme that looks striking at desktop width can put your menu behind an invisible button on mobile, and most of your visitors are on mobile.',
      'Pick a theme using the checklist rather than the screenshot: check the last-updated date, active installations and recent reviews before anything else. Install it, set your colours and fonts to no more than two of each, and build a menu with a maximum of six items. Then hand your phone to someone who has not seen the site and ask them to find the contact details. Time it.',
      '[{"question":"What is the first thing to check about a WordPress theme?","options":["When it was last updated — a stale theme is a security and compatibility risk","How impressive the demo screenshot looks","Whether it includes a slider","The number of colour options"],"correct_index":0},{"question":"How many top-level menu items should a small business site have?","options":["About five to seven, ordered by what visitors actually want","As many as the site has pages","Exactly three, always","One, with everything else nested inside it"],"correct_index":0}]'::jsonb),
    (v_m2, 'Plugins, Updates and Backups', 'WordPress''s own lesson on searching for, reviewing and installing plugins. About 4 minutes — the notes below add the maintenance side, which the video does not cover.', 'https://www.youtube.com/watch?v=WooNmrNKmcM', 2,
      array['Judge a plugin before installing it', 'Keep WordPress, themes and plugins updated without breaking the site', 'Have a backup you have actually tested restoring'],
      'Plugins are why WordPress runs a large share of the web, and also why so many WordPress sites get hacked. Both facts come from the same place: anyone can publish one, and you are installing their code into your site.

JUDGE A PLUGIN BEFORE INSTALLING, on four things:
- LAST UPDATED. Over a year ago, do not install it.
- ACTIVE INSTALLATIONS. Tens of thousands means problems get found and fixed.
- COMPATIBILITY with your WordPress version, which the plugin page states.
- RECENT SUPPORT THREADS. Are people being answered, or is the forum full of unanswered problems?

INSTALL AS FEW AS POSSIBLE. Every plugin is code running on every page load, another thing to update, and another possible way in. Sites with forty plugins are slow, fragile and hard to debug. If a plugin does one small thing you could do another way, do it the other way.

DELETE, DO NOT JUST DEACTIVATE. A deactivated plugin still sits on the server and can still be exploited. Remove what you are not using.

NOW THE PART THIS VIDEO DOES NOT COVER, and it matters more than the installing does.

UPDATES ARE SECURITY. The large majority of hacked WordPress sites were running a known vulnerability with a patch already available. Updating is not optional maintenance; it IS the security work. Check monthly at minimum.

BUT BACK UP BEFORE UPDATING. An update occasionally breaks a site, usually through a conflict between a plugin and a theme. With a backup that is twenty minutes of annoyance; without one it can be the whole site.

A BACKUP YOU HAVE NEVER RESTORED IS NOT A BACKUP. It is a file you hope is good. Restore one, once, onto a test site, so you know the procedure and know the file works. Most people discover their backup was broken on the day they needed it.

WHAT A REAL BACKUP INCLUDES: the DATABASE (all your posts, pages and settings) AND the FILES (uploads, themes, plugins). Either alone is not a restorable site. Keep a copy somewhere other than the server itself — if the host fails or the account is suspended, a backup stored on that host is gone too.

AND IF YOU MAINTAIN SITES FOR CLIENTS, this is a service worth charging a monthly fee for: updates, backups, uptime checks. It is recurring income, it is genuinely valuable, and it is the difference between building a site once and having a client for years.',
      'Take any WordPress site and audit its plugins: for each, check the last-updated date and active installations, and delete every one that is deactivated or that you cannot justify. Then set up a backup covering BOTH database and files, stored somewhere other than the host. Finally, do the step almost nobody does — restore that backup onto a test site and confirm it works.',
      '[{"question":"Why is a deactivated plugin still a risk?","options":["Its code remains on the server and can still be exploited — delete it instead","It continues to slow down page loads","It blocks WordPress core updates","It keeps sending data to its author"],"correct_index":0},{"question":"What makes a backup trustworthy?","options":["You have restored it at least once, and it covers both database and files, stored off the host","It runs automatically every night","It is stored on the same server for fast recovery","It includes the database, which is the only part that matters"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  -- Bring the shifted modules back, now sitting after the 2 new one(s).
  update public.modules set order_number = order_number - 1000 + 2
   where course_id = v_course_id and order_number > 1000;

end $$;
